// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 전체 질문 목록 (5번)" (10601936399347cda1caffc777e72f92).
// #23: 메인 화면. 질문 목록을 GET /api/questions에 연결하고 정렬 탭·페이지 번호를 붙였다.
import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { getErrorMessage } from "../api/client";
import { getQuestions, type Page, type QuestionListItem as Question, type QuestionSort } from "../api/question";
import Footer from "../components/Footer";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import Pagination from "../components/Pagination";
import QuestionListItem from "../components/QuestionListItem";
import SortTabs from "../components/SortTabs";
import { PAGE_SIZE, parsePage, parseSort, SORT_TABS } from "../components/questionList";
import { buttonClass, CARD, PAGE_BACKGROUND } from "../components/uiStyles";
import { formatNumber } from "../components/writer";
import "./Questions.css";

type LoadState =
  { status: "loading" } | { status: "error"; message: string } | { status: "done"; data: Page<Question> };

export default function Questions() {
  const [searchParams, setSearchParams] = useSearchParams();
  // URL의 ?sort=&page=를 읽는다. 화면의 page는 1부터, API의 page는 0부터 시작한다.
  const sort = parseSort(searchParams.get("sort"));
  const page = parsePage(searchParams.get("page"));
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [retryKey, setRetryKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading" });
    getQuestions({ sort, page: page - 1, size: PAGE_SIZE })
      .then((data) => {
        if (!cancelled) setState({ status: "done", data });
      })
      .catch((error: unknown) => {
        if (!cancelled) setState({ status: "error", message: getErrorMessage(error) });
      });
    return () => {
      cancelled = true;
    };
  }, [sort, page, retryKey]);

  function moveTo(next: { sort?: QuestionSort; page?: number }) {
    const params = new URLSearchParams();
    const nextSort = next.sort ?? sort;
    const nextPage = next.page ?? 1;
    if (nextSort !== "latest") params.set("sort", nextSort);
    if (nextPage > 1) params.set("page", String(nextPage));
    setSearchParams(params);
    window.scrollTo({ top: 0 });
  }

  const data = state.status === "done" ? state.data : null;

  return (
    <div id="page-questions">
      <div className={`min-h-screen flex flex-col justify-between antialiased text-devin-ink ${PAGE_BACKGROUND}`}>
        <Header />

        <main className="flex-1 max-w-6xl w-full mx-auto px-4 py-6">
          <div
            className="flex flex-col sm:flex-row items-start sm:items-end justify-between pb-3.5 gap-4"
            data-purpose="question-list-header"
          >
            <div className="flex items-baseline gap-2">
              <h1 className="text-2xl font-black">전체 질문</h1>
              {data && (
                <span className="text-sm font-semibold text-devin-gray tabular-nums">
                  {formatNumber(data.totalElements)}개
                </span>
              )}
            </div>

            <SortTabs tabs={SORT_TABS} value={sort} onChange={(next) => moveTo({ sort: next })} label="정렬" />
          </div>

          {/* 질문이 있으면 질문마다 카드(QuestionListItem)를 12px 띄워 쌓고, 불러오는 중·실패·빈 목록은 카드 하나에 보여 준다. */}
          <div
            className={data && data.content.length > 0 ? "flex flex-col gap-3" : CARD}
            data-purpose="question-items-container"
            aria-busy={state.status === "loading"}
          >
            {state.status === "loading" && <ListStatus kind="loading">질문을 불러오는 중이에요.</ListStatus>}
            {state.status === "error" && (
              <ListStatus
                kind="error"
                action={
                  <button
                    className={buttonClass("secondary", "sm")}
                    type="button"
                    onClick={() => setRetryKey((key) => key + 1)}
                  >
                    다시 시도
                  </button>
                }
              >
                {state.message}
              </ListStatus>
            )}
            {data && data.content.length === 0 && (
              <ListStatus kind="empty">
                {page > 1
                  ? "이 페이지에는 질문이 없어요. 앞 페이지로 돌아가 주세요."
                  : "아직 질문이 없어요. 첫 질문을 남겨 보세요."}
              </ListStatus>
            )}
            {data?.content.map((question) => (
              <QuestionListItem key={question.questionId} question={question} />
            ))}
          </div>

          <Pagination page={page} totalPages={data?.totalPages ?? 0} onChange={(next) => moveTo({ page: next })} />
        </main>

        <Footer />
      </div>
    </div>
  );
}
